WITH flattened AS (SELECT id, plan, currency, EXPLODE_OUTER(tier_limits) AS tier_value FROM price_tiers) SELECT id, plan, tier_value, PERCENT_RANK() OVER w_grp AS tier_value_percent_rank, RANK() OVER (PARTITION BY plan ORDER BY tier_value DESC) AS tier_value_rank, STDDEV_SAMP(tier_value) OVER (PARTITION BY currency, plan) AS currency_stddev_samp_tier_value, MIN(tier_value) OVER w_ordered AS plan_min_tier_value FROM flattened WINDOW w_grp AS (PARTITION BY currency ORDER BY tier_value NULLS FIRST), w_ordered AS (PARTITION BY plan);
